import { useState } from 'react';

export function Stepper() {
  const steps = {{steps}};
  const [current, setCurrent] = useState(0);
  return (
    <div className="flex items-center">
      {steps.map((s, i) => (
        <div key={i} className="flex items-center flex-1">
          <div className={`h-8 w-8 rounded-full flex items-center justify-center text-sm ${i <= current ? 'bg-blue-600 text-white' : 'bg-gray-200'}`}>
            {i + 1}
          </div>
          <span className="ml-2 text-sm">{s.label}</span>
          {i < steps.length - 1 && <div className={`flex-1 h-0.5 mx-3 ${i < current ? 'bg-blue-600' : 'bg-gray-200'}`} />}
        </div>
      ))}
    </div>
  );
}
